python3 -c '
import pdfplumber
import pandas as pd

with pdfplumber.open("/root/population.pdf") as pdf:
    for i, page in enumerate(pdf.pages):
        tables = page.extract_tables()
        print(f"Page {i} has {len(tables)} tables")
        for j, table in enumerate(tables):
            if table:
                print(f"  Table {j} first 3 rows:")
                for row in table[:3]:
                    print(f"    {row}")
'
